(() => {
  'use strict';
  const canvas = document.getElementById('view');
  const ctx = canvas.getContext('2d', { alpha: false });
  const ui = Object.fromEntries(['intro','hud','pauseScreen','endScreen','startButton','resumeButton','restartButton','objective','progressFill','memoryCount','signalReadout','batteryValue','batteryFill','noiseFill','hint','interactPrompt','statusText','flash','endEyebrow','endTitle','endCopy','finalStats','mobileControls'].map(id => [id, document.getElementById(id)]));
  const TAU = Math.PI * 2;
  const WORLD = 25;
  let map, memories, exit, stalker, player, zBuffer = [], w = 640, h = 360, running = false, ended = false, startedAt = 0, lastTime = 0, noise = 0, battery = 100, lightOn = true, found = 0, steps = 0, lastThreat = 0, audioCtx, humGain, sirenOsc;
  const keys = new Set(), touch = new Set();
  const hints = ['The lights are listening.','Somewhere, something is moving.','Do not let it get close.','The hum is coming from everywhere.','You are not alone in here.'];
  let hintTime = 0;

  function resize(){
    const ratio = innerWidth / innerHeight;
    w = Math.min(800, Math.max(480, Math.round(600 * Math.min(1.33, ratio))));
    h = Math.round(w / ratio);
    canvas.width = w; canvas.height = h;
    zBuffer = new Float32Array(w);
  }
  addEventListener('resize', resize); resize();

  function makeMap(){
    const m = Array.from({length:WORLD},()=>Array(WORLD).fill(1));
    const visited = new Set();
    const stack = [[1,1]]; m[1][1]=0; visited.add('1,1');
    while(stack.length){
      const [x,y] = stack[stack.length-1];
      const dirs = [[0,-2],[2,0],[0,2],[-2,0]].sort(()=>Math.random()-.5);
      const next = dirs.map(([dx,dy])=>[x+dx,y+dy,dx,dy]).filter(([nx,ny])=>nx>0&&ny>0&&nx<WORLD-1&&ny<WORLD-1&&!visited.has(`${nx},${ny}`));
      if(!next.length){stack.pop();continue;}
      const [nx,ny,dx,dy]=next[0]; visited.add(`${nx},${ny}`);m[ny][nx]=0;m[y+dy/2][x+dx/2]=0;stack.push([nx,ny]);
    }
    // A few accidental breaches make the maze feel like a broken floor plan.
    for(let i=0;i<24;i++){
      const x=2+Math.floor(Math.random()*(WORLD-4)),y=2+Math.floor(Math.random()*(WORLD-4));
      if(m[y][x]===1&&((m[y-1][x]===0&&m[y+1][x]===0)||(m[y][x-1]===0&&m[y][x+1]===0)))m[y][x]=0;
    }
    return m;
  }
  const floor=(x,y)=>x>=0&&y>=0&&x<WORLD&&y<WORLD&&map[y][x]===0;
  function distances(sx,sy){
    const d=Array.from({length:WORLD},()=>Array(WORLD).fill(Infinity)),q=[[sx,sy]]; d[sy][sx]=0;
    for(let i=0;i<q.length;i++){const [x,y]=q[i];for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy;if(floor(nx,ny)&&d[ny][nx]===Infinity){d[ny][nx]=d[y][x]+1;q.push([nx,ny]);}}}
    return d;
  }
  function newGame(){
    map=makeMap(); player={x:1.5,y:1.5,angle:Math.PI*.12};
    const d=distances(1,1), candidates=[];
    for(let y=1;y<WORLD-1;y++)for(let x=1;x<WORLD-1;x++)if(floor(x,y)&&d[y][x]>5)candidates.push({x:x+.5,y:y+.5,d:d[y][x]});
    candidates.sort((a,b)=>a.d-b.d);
    const far=candidates[candidates.length-1]; exit={x:far.x,y:far.y,open:false};
    const spots=[];
    for(const target of [.30,.52,.73]){
      const desired=Math.floor(far.d*target);let eligible=candidates.filter(p=>p.d>Math.max(9,desired-4)&&p.d<desired+5&&spots.every(s=>Math.hypot(s.x-p.x,s.y-p.y)>5));
      if(!eligible.length)eligible=candidates.filter(p=>p.d>10&&spots.every(s=>Math.hypot(s.x-p.x,s.y-p.y)>4));
      const pick=eligible[Math.floor(Math.random()*eligible.length)];if(pick)spots.push(pick);
    }
    memories=spots.map((p,i)=>({...p,id:i,got:false,phase:Math.random()*TAU}));
    const enemyOptions=candidates.filter(p=>p.d>=8&&p.d<=15&&Math.hypot(p.x-1.5,p.y-1.5)>6);
    const ep=enemyOptions[Math.floor(Math.random()*enemyOptions.length)]||candidates[10];
    stalker={x:ep?.x||far.x,y:ep?.y||far.y,moveAt:0,awake:false};
    found=0;noise=0;battery=100;lightOn=true;steps=0;ended=false;lastThreat=0;startedAt=performance.now();
    updateHud();
  }

  // Procedural wallpaper keeps every run asset-free and slightly wrong.
  const wallTex=document.createElement('canvas');wallTex.width=256;wallTex.height=256;
  const wt=wallTex.getContext('2d');
  wt.fillStyle='#b8a965';wt.fillRect(0,0,256,256);
  for(let y=0;y<256;y+=32){wt.fillStyle=y%64===0?'#d1c17c':'#b8aa68';wt.fillRect(0,y,256,31);wt.fillStyle='#766d43';wt.fillRect(0,y+30,256,2);wt.fillStyle='#e3d49355';wt.fillRect(0,y+2,256,2);}
  for(let i=0;i<5000;i++){const a=Math.random()*.15;wt.fillStyle=Math.random()>.5?`rgba(46,39,22,${a})`:`rgba(255,239,155,${a})`;wt.fillRect(Math.random()*256,Math.random()*256,1+Math.random()*4,1+Math.random()*3);}
  for(let i=0;i<12;i++){const x=Math.random()*256,y=Math.random()*256,r=8+Math.random()*24,g=wt.createRadialGradient(x,y,1,x,y,r);g.addColorStop(0,'rgba(61,56,30,.24)');g.addColorStop(1,'rgba(61,56,30,0)');wt.fillStyle=g;wt.fillRect(x-r,y-r,r*2,r*2);}
  const floorTex=document.createElement('canvas');floorTex.width=floorTex.height=64;const ft=floorTex.getContext('2d');
  ft.fillStyle='#706c51';ft.fillRect(0,0,64,64);for(let i=0;i<1100;i++){ft.fillStyle=Math.random()>.5?'rgba(26,27,19,.15)':'rgba(220,207,147,.09)';ft.fillRect(Math.random()*64,Math.random()*64,1+Math.random()*3,1+Math.random()*2);}

  function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
  function wallAt(x,y){return !floor(x,y);}
  function canMove(x,y,r=.19){return !wallAt(Math.floor(x-r),Math.floor(y-r))&&!wallAt(Math.floor(x+r),Math.floor(y-r))&&!wallAt(Math.floor(x-r),Math.floor(y+r))&&!wallAt(Math.floor(x+r),Math.floor(y+r));}
  function movePlayer(dx,dy){if(canMove(player.x+dx,player.y))player.x+=dx;if(canMove(player.x,player.y+dy))player.y+=dy;}
  function flash(){ui.flash.classList.remove('pulse');void ui.flash.offsetWidth;ui.flash.classList.add('pulse');}
  function nearestThing(){let best=null,dist=1.5;for(const m of memories)if(!m.got){const d=Math.hypot(player.x-m.x,player.y-m.y);if(d<dist){dist=d;best={type:'memory',item:m,d};}}const ed=Math.hypot(player.x-exit.x,player.y-exit.y);if(ed<dist){dist=ed;best={type:'exit',item:exit,d:ed};}return best;}
  function interact(){if(!running||ended)return;const thing=nearestThing();if(!thing)return;if(thing.type==='memory'){thing.item.got=true;found++;noise=clamp(noise+12,0,100);flash();updateHud();if(found===3){ui.objective.textContent='Find the way out';ui.signalReadout.textContent='SIGNAL FOUND';}}else if(found>=3){win();}else{ui.hint.textContent=`The door won't move. ${3-found} memories remain.`;noise=clamp(noise+6,0,100);}}
  function updateHud(){ui.memoryCount.textContent=`${found} / 3 recovered`;ui.progressFill.style.width=`${found/3*100}%`;ui.batteryValue.textContent=`${Math.ceil(battery)}%`;ui.batteryFill.style.width=`${battery}%`;ui.batteryFill.style.background=battery<20?'#bc5140':'';ui.signalReadout.textContent=found===3?'SIGNAL FOUND':'NO SIGNAL';}

  function drawWorld(time){
    const horizon=Math.floor(h*.51+Math.sin(time*.001)*1.3);ctx.fillStyle='#55513b';ctx.fillRect(0,0,w,horizon);ctx.fillStyle='#353529';ctx.fillRect(0,horizon,w,h-horizon);
    const ceiling=ctx.createLinearGradient(0,0,0,horizon);ceiling.addColorStop(0,'#444335');ceiling.addColorStop(1,'#716948');ctx.fillStyle=ceiling;ctx.fillRect(0,0,w,horizon);
    const floorGrad=ctx.createLinearGradient(0,horizon,0,h);floorGrad.addColorStop(0,'#6d6849');floorGrad.addColorStop(1,'#292a21');ctx.fillStyle=floorGrad;ctx.fillRect(0,horizon,w,h-horizon);
    // Perspective floor texture.
    const data=ft.getImageData(0,0,64,64).data;
    for(let y=horizon+1;y<h;y+=2){const rowDistance=(.52*h)/(y-horizon);for(let x=0;x<w;x+=2){const cam=(2*x/w-1);const wx=player.x+Math.cos(player.angle)*rowDistance-Math.sin(player.angle)*cam*rowDistance*.66;const wy=player.y+Math.sin(player.angle)*rowDistance+Math.cos(player.angle)*cam*rowDistance*.66;const tx=(Math.floor(wx*16)&63),ty=(Math.floor(wy*16)&63),ii=(ty*64+tx)*4;let shade=clamp(1.15-rowDistance*.045,.22,1);if(lightOn){const a=Math.atan2(wy-player.y,wx-player.x),da=Math.abs(Math.atan2(Math.sin(a-player.angle),Math.cos(a-player.angle)));shade+=Math.max(0,.35-da)*.62/(1+rowDistance*.38);}ctx.fillStyle=`rgb(${data[ii]*shade|0},${data[ii+1]*shade|0},${data[ii+2]*shade|0})`;ctx.fillRect(x,y,2,2);}}
    const dirX=Math.cos(player.angle),dirY=Math.sin(player.angle),planeX=-dirY*.66,planeY=dirX*.66;
    for(let x=0;x<w;x++){
      const cameraX=2*x/w-1,rayX=dirX+planeX*cameraX,rayY=dirY+planeY*cameraX;let mx=Math.floor(player.x),my=Math.floor(player.y),deltaX=Math.abs(1/rayX),deltaY=Math.abs(1/rayY),stepX,stepY,sideX,sideY;
      if(rayX<0){stepX=-1;sideX=(player.x-mx)*deltaX;}else{stepX=1;sideX=(mx+1-player.x)*deltaX;}if(rayY<0){stepY=-1;sideY=(player.y-my)*deltaY;}else{stepY=1;sideY=(my+1-player.y)*deltaY;}
      let side=0,guard=0;while(guard++<70){if(sideX<sideY){sideX+=deltaX;mx+=stepX;side=0;}else{sideY+=deltaY;my+=stepY;side=1;}if(wallAt(mx,my))break;}
      let dist=side===0?sideX-deltaX:sideY-deltaY;dist=Math.max(.08,dist);zBuffer[x]=dist;const wallHeight=Math.min(h*3,h/dist),top=Math.floor(horizon-wallHeight*.51),bottom=Math.floor(horizon+wallHeight*.49);
      let hit=side===0?player.y+dist*rayY:player.x+dist*rayX;hit-=Math.floor(hit);let tx=Math.floor(hit*256);if(side===0&&rayX>0)tx=255-tx;if(side===1&&rayY<0)tx=255-tx;
      let shade=clamp(1.08-dist*.105,.12,1)*(side===1?.78:1);const lightAngle=Math.atan2(rayY,rayX),angleDiff=Math.abs(Math.atan2(Math.sin(lightAngle-player.angle),Math.cos(lightAngle-player.angle)));if(lightOn&&angleDiff<.52)shade+=.95*(1-angleDiff/.52)/(1+dist*.35);
      const tex=wt.getImageData(tx,0,1,256);const temp=document.createElement('canvas'); // Reused through a 1px strip buffer below.
      wallColumnCtx.putImageData(tex,0,0);ctx.globalAlpha=1;ctx.drawImage(wallColumn,0,0,1,256,x,top,Math.ceil(w/w),bottom-top);
      // Per-column lighting overlay creates the long, dirty falloff.
      ctx.fillStyle=`rgba(12,13,9,${clamp(1-shade,.05,.88)})`;ctx.fillRect(x,top,1,bottom-top);
    }
    ctx.globalAlpha=1;drawSprites(time,horizon,dirX,dirY,planeX,planeY);
    // A barely-visible fluorescent flicker above the horizon.
    if(Math.sin(time*.007)>-.7){ctx.fillStyle='#f8eab0';ctx.globalAlpha=.06+Math.random()*.04;ctx.fillRect(w*.35,Math.max(0,horizon-53),w*.28,2);ctx.globalAlpha=1;}
    // Keep the handheld beam concentrated, with a soft falloff.
    if(lightOn){const g=ctx.createRadialGradient(w/2,horizon,w*.04,w/2,horizon,w*.62);g.addColorStop(0,'rgba(245,232,177,.10)');g.addColorStop(.38,'rgba(230,216,163,.035)');g.addColorStop(1,'rgba(5,6,5,.25)');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);}
  }
  const wallColumn=document.createElement('canvas');wallColumn.width=1;wallColumn.height=256;const wallColumnCtx=wallColumn.getContext('2d');

