  function drawSprites(time,horizon,dirX,dirY,planeX,planeY){
    const inv=1/(planeX*dirY-dirX*planeY),sprites=[];
    for(const m of memories)if(!m.got)sprites.push({type:'memory',x:m.x,y:m.y,phase:m.phase,dist:(m.x-player.x)**2+(m.y-player.y)**2});
    sprites.push({type:'exit',x:exit.x,y:exit.y,dist:(exit.x-player.x)**2+(exit.y-player.y)**2});
    sprites.push({type:'entity',x:stalker.x,y:stalker.y,dist:(stalker.x-player.x)**2+(stalker.y-player.y)**2});
    sprites.sort((a,b)=>b.dist-a.dist);
    for(const s of sprites){
      const dx=s.x-player.x,dy=s.y-player.y,tx=inv*(dirY*dx-dirX*dy),ty=inv*(-planeY*dx+planeX*dy);if(ty<=.15)continue;
      const sx=Math.floor(w/2*(1+tx/ty)),height=Math.min(h*2,h/ty*(s.type==='entity'?1.1:.7)),sw=s.type==='exit'?height*.55:height*.42,top=horizon-height*.52;
      if(sx+sw/2<0||sx-sw/2>=w)continue;
      if(s.type==='memory'){
        if(zBuffer[clamp(sx|0,0,w-1)]<ty-.15)continue;
        const bob=Math.sin(time*.002+s.phase)*height*.035,cy=top+height*.48+bob,r=Math.max(2,height*.085);
        ctx.save();ctx.globalCompositeOperation='screen';const glow=ctx.createRadialGradient(sx,cy,1,sx,cy,r*4);glow.addColorStop(0,'rgba(250,229,149,.75)');glow.addColorStop(1,'rgba(242,204,86,0)');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(sx,cy,r*4,0,TAU);ctx.fill();ctx.fillStyle='#f8e9ae';ctx.shadowColor='#f5d875';ctx.shadowBlur=14;ctx.beginPath();ctx.moveTo(sx,cy-r);ctx.lineTo(sx+r*.75,cy);ctx.lineTo(sx,cy+r);ctx.lineTo(sx-r*.75,cy);ctx.closePath();ctx.fill();ctx.restore();
      } else if(s.type==='exit'){
        if(zBuffer[clamp(sx|0,0,w-1)]<ty-.2)continue;
        const base=top+height*.96;ctx.save();ctx.globalAlpha=.72;ctx.strokeStyle=found>=3?'#a2d68c':'#aaa178';ctx.lineWidth=Math.max(1,height*.025);ctx.shadowColor=found>=3?'#9ad47f':'#ddd092';ctx.shadowBlur=found>=3?18:7;ctx.strokeRect(sx-sw*.34,top+height*.18,sw*.68,height*.78);ctx.fillStyle=found>=3?'rgba(130,190,115,.12)':'rgba(172,157,94,.08)';ctx.fillRect(sx-sw*.31,top+height*.2,sw*.62,height*.74);ctx.fillStyle=found>=3?'#b4e296':'#c5b77b';ctx.fillRect(sx-sw*.34,base-height*.04,sw*.68,height*.035);ctx.restore();
      }else{
        if(zBuffer[clamp(sx|0,0,w-1)]<ty-.24)continue;
        const base=top+height*.98,scale=height;ctx.save();ctx.translate(sx,base);ctx.scale(scale,scale);ctx.globalAlpha=clamp(1-ty/15,.25,.96);
        // Wrongly long limbs and a head that is all shadow.
        ctx.fillStyle='#080a08';ctx.shadowColor='#040504';ctx.shadowBlur=8;
        ctx.beginPath();ctx.ellipse(0,-.73,.125,.18,0,0,TAU);ctx.fill();
        ctx.beginPath();ctx.moveTo(-.12,-.64);ctx.quadraticCurveTo(-.28,-.48,-.17,-.28);ctx.lineTo(-.23,-.03);ctx.quadraticCurveTo(-.13,.02,0,-.03);ctx.quadraticCurveTo(.18,.02,.22,-.06);ctx.lineTo(.11,-.31);ctx.quadraticCurveTo(.23,-.53,.1,-.64);ctx.closePath();ctx.fill();
