(() => {
  'use strict';
  const canvas=document.getElementById('view'),ctx=canvas.getContext('2d',{alpha:false});
  const ui=Object.fromEntries(['intro','hud','pauseScreen','endScreen','startButton','resumeButton','restartButton','objective','progressFill','memoryCount','signalReadout','batteryValue','batteryFill','noiseFill','hint','interactPrompt','statusText','flash','endEyebrow','endTitle','endCopy','finalStats'].map(id=>[id,document.getElementById(id)]));
  const TAU=Math.PI*2,WORLD=25,keys=new Set(),touch=new Set(),hints=['The lights are listening.','Somewhere, something is moving.','Do not let it get close.','The hum is coming from everywhere.','You are not alone in here.'];
  let map,memories,exit,stalker,player,zBuffer=[],w=640,h=360,running=false,ended=false,lastTime=0,noise=0,battery=100,lightOn=true,found=0,steps=0,audioCtx,humGain,sirenOsc,hintTime=0;
  function resize(){const ratio=innerWidth/innerHeight;w=Math.min(800,Math.max(480,Math.round(600*Math.min(1.33,ratio))));h=Math.round(w/ratio);canvas.width=w;canvas.height=h;zBuffer=new Float32Array(w);}addEventListener('resize',resize);resize();
  function makeMap(){const m=Array.from({length:WORLD},()=>Array(WORLD).fill(1)),visited=new Set(),stack=[[1,1]];m[1][1]=0;visited.add('1,1');while(stack.length){const [x,y]=stack[stack.length-1],dirs=[[0,-2],[2,0],[0,2],[-2,0]].sort(()=>Math.random()-.5),next=dirs.map(([dx,dy])=>[x+dx,y+dy,dx,dy]).filter(([nx,ny])=>nx>0&&ny>0&&nx<WORLD-1&&ny<WORLD-1&&!visited.has(`${nx},${ny}`));if(!next.length){stack.pop();continue;}const [nx,ny,dx,dy]=next[0];visited.add(`${nx},${ny}`);m[ny][nx]=0;m[y+dy/2][x+dx/2]=0;stack.push([nx,ny]);}for(let i=0;i<24;i++){const x=2+Math.floor(Math.random()*(WORLD-4)),y=2+Math.floor(Math.random()*(WORLD-4));if(m[y][x]===1&&((m[y-1][x]===0&&m[y+1][x]===0)||(m[y][x-1]===0&&m[y][x+1]===0)))m[y][x]=0;}return m;}
